function architecturalTexture(kind){const c=document.createElement('canvas');c.width=512;c.height=512;const x=c.getContext('2d');x.fillStyle=kind==='brick'?'#895c50':kind==='plaza'?'#7f8787':'#a4aaab';x.fillRect(0,0,512,512);let seed=79;const rand=()=>{seed=(seed*16807)%2147483647;return(seed-1)/2147483646;};for(let i=0;i<14000;i++){const v=rand()*40;x.fillStyle=`rgba(${v},${v},${v},.08)`;x.fillRect(rand()*512,rand()*512,2,2);}x.strokeStyle=kind==='brick'?'#3c342e':'#656c6d';x.lineWidth=2;const h=kind==='brick'?24:64,w=kind==='brick'?76:64;for(let row=0;row<512/h;row++){x.beginPath();x.moveTo(0,row*h);x.lineTo(512,row*h);x.stroke();for(let j=-1;j<512/w;j++){const px=j*w+(row%2)*w/2;x.beginPath();x.moveTo(px,row*h);x.lineTo(px,(row+1)*h);x.stroke();}}const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;t.wrapS=t.wrapT=THREE.RepeatWrapping;t.repeat.set(kind==='plaza'?12:4,kind==='plaza'?12:2);t.anisotropy=4;return t;}
